mapper.select:
/* com.heeji.picket.mapper.UserMapper.info */
SELECT  *
FROM    USER
WHERE   1 = 1
AND     EMAIL = #{email}

AND     PASSWORD = #{password}

mapper.update:
UPDATE  USER
SET     UPDATE_DATE = NOW()
,       PASSWORD = #{password}
,       ROLE = #{role}
,       NAME = #{name}
,       PHONE_NUMBER = #{phoneNumber}
,       ADDRESS = #{address}
,       DETAIL_ADDRESS = #{detailAddress}
,       IS_DELETED = #{isDeleted}
,       DELETE_DATE = #{deleteDate}
,       PROVIDER_TYPE = #{providerType}
,       EMAIL_ON = #{emailOn}

mapper.delete:
/* com.heeji.picket.mapper.UserMapper.delete */
DELETE FROM USER
WHERE       1 = 1
AND         EMAIL = #{email}
